function ghostHtml(sub){return `<span class="board-icon">${catIcon(sub.cat)}</span><span><small>${sub.replace?'Ersetzen · ':''}${E(sub.cat?L.label(sub.cat,sub.e):'Aufgabe')}</small><strong>${E(sub.t?.title||'Aufgabe')}</strong></span>`;}
