 let moved=false;
 for(const sc of [$('.paper-stage'),$('.paper-library')]){const r=sc?.getBoundingClientRect?.();if(!r||x<r.left||x>r.right)continue;const before=sc.scrollTop;if(y<r.top+64&&y>=r.top-12)sc.scrollTop-=edgeSpeed(y-r.top);else if(y>r.bottom-64&&y<=r.bottom+12)sc.scrollTop+=edgeSpeed(r.bottom-y);if(sc.scrollTop!==before)moved=true;}
