function moveExamItem(id,to){const e=editableExam(),i=e.items.findIndex(x=>x.id===id);if(i<0)return null;const j=Math.max(0,Math.min(e.items.length-1,to));if(i===j)return {pos:j+1,total:e.items.length,title:e.items[i].task.title,moved:false};if(historyTimer)recordHistory();const [item]=e.items.splice(i,1);e.items.splice(j,0,item);e.updatedAt=C.now();changed();render();return {pos:j+1,total:e.items.length,title:item.task.title,moved:true};}
